css:
/* =====================================================================
   LIFE · CLUSTER COMMAND CENTER — PREMIUM THEME v4
   Web Page: new-cluster-dashboard-bhuvan  (route: branch-command-center-C-DB)
   REPLACES the entire "Style" (CSS) field. Business JS untouched.
   ===================================================================== */

/* ---------- 0. Portal chrome ---------- */
.navbar,.web-footer,.page-header{display:none!important}
.container{max-width:none!important;width:100%!important}
.page-content-wrapper,.page_content{padding:0!important}
html{scroll-behavior:smooth}
body{background:#F2F6F4!important}

/* ---------- 1. Tokens ---------- */
#clusterApp{
  --g950:#04281A;--g900:#063D27;--g800:#0A5636;--g700:#0E7A4F;--g600:#13925F;--teal:#0F766E;
  --mint:#ECF8F1;--mint2:#DDF2E6;--mint3:#F6FBF8;
  --ink:#1B2A24;--ink2:#33463E;--mut:#5C6E66;--mut2:#7D8E86;
  --line:#D9E6DF;--line2:#E8F0EB;--card:#FFFFFF;--bg:#F2F6F4;
  --gold:#B8862B;--gold2:#E9CF8A;--goldbg:#FFF8E6;
  --ok:#15803D;--okbg:#E7F6EC;--warn:#B45309;--warnbg:#FFF4E2;--bad:#B4232F;--badbg:#FDECEE;
  --info:#1D5FA8;--infobg:#EAF2FC;--special:#6D3FB8;--specialbg:#F3EEFC;
  --r-lg:14px;--r-md:10px;--r-sm:7px;
  --sh1:0 1px 2px rgba(6,61,39,.06),0 2px 8px rgba(6,61,39,.05);
  --sh2:0 4px 14px rgba(6,61,39,.10),0 1px 3px rgba(6,61,39,.06);
  --clx-sticky-h:96px;
  max-width:1840px;margin:0 auto;padding:0 22px 40px;
  color:var(--ink);font:14px/1.45 Inter,"Segoe UI",system-ui,-apple-system,sans-serif;
  -webkit-font-smoothing:antialiased;font-variant-numeric:tabular-nums;background:var(--bg)
}
#clusterApp *{box-sizing:border-box}
#clusterApp [hidden]{display:none!important}
#clusterApp h1,#clusterApp h2,#clusterApp h3{color:var(--g900);letter-spacing:-.2px}

/* ---------- 2. Controls (buttons / inputs) ---------- */
#clusterApp button,#clusterApp select,#clusterApp input{font:inherit;font-size:13px}
#clusterApp button{cursor:pointer;border:1px solid var(--line);border-radius:var(--r-sm);background:#fff;color:var(--g800);
  padding:7px 12px;font-weight:600;line-height:1.2;transition:background .15s,border-color .15s,color .15s,box-shadow .15s}
#clusterApp button:hover:not(:disabled){border-color:var(--g700);background:var(--mint)}
#clusterApp button:disabled{opacity:.55;cursor:not-allowed}
#clusterApp select,#clusterApp input[type=date],#clusterApp input[type=search],#clusterApp input:not([type]){
  border:1px solid #C9D9D0;border-radius:var(--r-sm);background:#fff;color:var(--ink);padding:7px 10px;min-height:34px}
#clusterApp select{cursor:pointer}
#clusterApp select:hover,#clusterApp input:hover{border-color:var(--g700)}
#clusterApp button:focus-visible,#clusterApp a:focus-visible,#clusterApp select:focus-visible,#clusterApp input:focus-visible,
#clusterApp summary:focus-visible,#clusterApp [role=button]:focus-visible,#clusterApp td:focus-visible{outline:3px solid #7FD1A8;outline-offset:2px}
#clusterApp a{color:var(--g700);font-weight:600}

/* ---------- 3. Header ---------- */
#clusterApp .cl-header{display:flex;align-items:center;justify-content:space-between;gap:20px;flex-wrap:wrap;
  padding:16px 22px;margin:0 -22px;border-radius:0;color:#fff;
  background:radial-gradient(120% 160% at 0% 0%,#0F6A45 0%,var(--g900) 55%,var(--g950) 100%);
  border-bottom:2px solid var(--gold2);box-shadow:0 6px 20px rgba(4,40,26,.18)}
#clusterApp .cl-brand{display:flex;align-items:center;gap:14px;min-width:0}
#clusterApp .cl-brand>a{display:grid;place-items:center;width:46px;height:46px;flex:none;border-radius:13px;text-decoration:none;
  font:700 26px Georgia,"Times New Roman",serif;color:var(--g900);background:linear-gradient(145deg,#FFF3CF,#E2C273);
  box-shadow:0 2px 8px rgba(0,0,0,.25),inset 0 1px 0 #fff}
#clusterApp .cl-brand>a:hover{transform:translateY(-1px)}
#clusterApp .cl-brand small{display:block;font-size:11px;font-weight:700;letter-spacing:2px;color:#BFE6D1}
#clusterApp .cl-brand h1{margin:2px 0 3px;font-size:26px;font-weight:750;color:#fff!important;letter-spacing:-.4px;line-height:1.15}
#clusterApp .cl-grand{display:inline-block;font-size:12.5px;font-weight:600;color:#FFE7A8;background:rgba(255,255,255,.08);
  border:1px solid rgba(255,231,168,.35);border-radius:20px;padding:2px 10px}
#clusterApp .cl-controls{display:flex;align-items:center;gap:12px;flex-wrap:wrap}
#clusterApp .cl-controls label{display:flex;align-items:center;gap:10px;margin:0;font-size:11px;font-weight:700;letter-spacing:1.4px;color:#BFE6D1}
#clusterApp .cl-controls select{min-width:240px;background:#fff;border:1px solid rgba(255,255,255,.6);color:var(--g900);font-weight:700}
#clusterApp .cl-controls select:disabled{opacity:1;background:#F3FAF6;cursor:default}
#clusterApp .cl-profile{width:44px;height:44px;flex:none;display:grid;place-items:center;overflow:hidden;border-radius:50%;
  border:2px solid var(--gold2);background:#F5E7BC;color:var(--g900);font-weight:800;font-size:17px;box-shadow:0 2px 8px rgba(0,0,0,.25)}
#clusterApp .cl-profile img{width:100%;height:100%;object-fit:cover}
#clusterApp #cl-refresh{background:#fff;color:var(--g900);border-color:#fff;padding:9px 16px;font-weight:700}
#clusterApp #cl-refresh:hover:not(:disabled){background:#FFF3CF;border-color:#FFF3CF}
#clusterApp.clx-busy #cl-refresh::before{content:"";display:inline-block;width:12px;height:12px;margin-right:7px;vertical-align:-2px;
  border:2px solid var(--g700);border-right-color:transparent;border-radius:50%;animation:clxSpin .8s linear infinite}
@keyframes clxSpin{to{transform:rotate(360deg)}}

/* ---------- 4. Sticky bar: tabs + scoreboard ---------- */
#clusterApp .clx-sticky{position:sticky;top:0;z-index:40;margin:0 -22px;padding:8px 22px 8px;
  background:rgba(242,246,244,.94);backdrop-filter:saturate(1.4) blur(8px);-webkit-backdrop-filter:saturate(1.4) blur(8px);
  border-bottom:1px solid var(--line)}
#clusterApp .cl-tabs{display:flex;align-items:center;gap:6px;flex-wrap:nowrap;overflow-x:auto;padding:4px 0 8px;scrollbar-width:thin}
#clusterApp .cl-tabs button{flex:none;font-size:13px;font-weight:600;padding:7px 13px;border-radius:20px;
  background:#fff;border:1px solid var(--line);color:var(--ink2);white-space:nowrap}
#clusterApp .cl-tabs button:hover{color:var(--g900);border-color:var(--g700);background:var(--mint)}
#clusterApp .cl-tabs button.active,#clusterApp .cl-tabs button[aria-current=true]{
  background:linear-gradient(135deg,var(--g800),var(--teal))!important;color:#fff!important;border-color:transparent!important;box-shadow:var(--sh1)}
#clusterApp .cl-tabs>#cl-period{flex:none;margin-left:auto;font-size:12px;font-weight:600;color:var(--mut);
  background:#fff;border:1px solid var(--line);border-radius:20px;padding:6px 11px;white-space:nowrap}
#clusterApp .cl-tabs .clx-tabtools{display:inline-flex;gap:4px;flex:none}
#clusterApp .cl-tabs .clx-tabtools button{border-radius:var(--r-sm);font-size:12px;padding:6px 10px;color:var(--mut)}

#clusterApp .cl-score{display:flex;align-items:stretch;min-height:40px;overflow:hidden;border-radius:var(--r-md);
  background:linear-gradient(100deg,var(--g900),#0C5A3B 60%,#0E6B58);color:#D9F0E4;border:1px solid #0A4A30;box-shadow:var(--sh2);font-size:13px}
#clusterApp .cl-score>div{display:flex;align-items:center;gap:6px;padding:0 16px;white-space:nowrap;border-right:1px solid rgba(255,255,255,.12)}
#clusterApp .cl-score>div[data-jump]{cursor:pointer;transition:background .15s}
#clusterApp .cl-score>div[data-jump]:hover{background:rgba(255,255,255,.08)}
#clusterApp .cl-score b{color:#FFE7A8;font-size:14.5px;font-weight:750;margin-left:2px}
#clusterApp .cl-score .cl-score-ticker{flex:1;min-width:0;overflow:hidden;border:0;padding:0 14px;cursor:pointer;
  -webkit-mask-image:linear-gradient(90deg,transparent,#000 4%,#000 94%,transparent);mask-image:linear-gradient(90deg,transparent,#000 4%,#000 94%,transparent)}
#clusterApp #cl-ticker{display:inline-flex;align-items:center;gap:30px;white-space:nowrap;padding-left:20px;animation:clTicker 75s linear infinite}
#clusterApp .cl-score:hover #cl-ticker{animation-play-state:paused}
@keyframes clTicker{from{transform:translateX(15%)}to{transform:translateX(-100%)}}
#clusterApp .cl-ticker-item{display:inline-flex;align-items:center;gap:6px;font-size:13px}
#clusterApp .cl-ticker-item em{font-style:normal}
#clusterApp .cl-ticker-item b{color:#fff;font-size:13px;margin:0}
#clusterApp .cl-ticker-item small{color:#9FD9BE;font-size:11.5px;font-weight:700}
#clusterApp .cl-ticker-item strong{color:#FFE7A8}

/* branch-focus chip (added by script) */
#clusterApp .clx-focus{display:none;align-items:center;gap:8px;margin-top:8px;font-size:13px;color:var(--g900)}
#clusterApp .clx-focus.on{display:flex}
#clusterApp .clx-focus span{background:var(--mint);border:1px solid #A9D9BF;border-radius:20px;padding:4px 6px 4px 12px;display:inline-flex;align-items:center;gap:8px;font-weight:600}
#clusterApp .clx-focus button{padding:2px 8px;border-radius:14px;font-size:12px}

/* ---------- 5. Status line ---------- */
#clusterApp #cl-status{display:block;margin:10px 0 2px;padding:0;min-height:18px;font-size:12px;color:var(--mut);
  white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
#clusterApp #cl-status::before{content:"";display:inline-block;width:7px;height:7px;border-radius:50%;background:var(--g600);margin-right:7px;vertical-align:1px;box-shadow:0 0 0 3px rgba(19,146,95,.18)}
#clusterApp.clx-busy #cl-status::before{background:var(--warn);box-shadow:0 0 0 3px rgba(180,83,9,.18);animation:clxPulse 1s ease-in-out infinite}
@keyframes clxPulse{50%{opacity:.35}}
#clusterApp .cl-intro{display:none}

/* ---------- 6. KPI cards ---------- */
#clusterApp .cl-cards{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:12px;margin:10px 0 16px}
#clusterApp .cl-card{--accent:var(--g700);--tint:var(--mint);position:relative;display:flex;flex-direction:column;align-items:stretch;gap:2px;
  width:100%;min-height:128px;text-align:left;padding:14px 16px 30px;border-radius:var(--r-lg);overflow:hidden;
  background:#fff;border:1px solid var(--line);border-top:4px solid var(--accent);box-shadow:var(--sh1);color:var(--ink);
  transition:transform .15s,box-shadow .15s,border-color .15s}
#clusterApp .cl-card::before{content:"";position:absolute;inset:0 0 auto 0;height:44px;background:linear-gradient(180deg,var(--tint),transparent);pointer-events:none}
#clusterApp .cl-card::after{content:"View details ›";position:absolute;left:16px;bottom:9px;font-size:11.5px;font-weight:700;color:var(--accent);opacity:.75}
#clusterApp .cl-card:hover{transform:translateY(-2px);box-shadow:var(--sh2);border-color:var(--accent);background:#fff!important}
#clusterApp .cl-card:hover::after{opacity:1}
#clusterApp .cl-card>*{position:relative}
#clusterApp .cl-card small{display:block;font-size:12px;font-weight:700;letter-spacing:.3px;text-transform:uppercase;color:var(--ink2)}
#clusterApp .cl-card strong{display:block;font-size:26px;font-weight:800;letter-spacing:-.5px;line-height:1.15;margin:6px 0 2px;color:var(--accent)}
#clusterApp .cl-card strong:empty{display:none}
#clusterApp .cl-card p{margin:4px 0 0;font-size:12px;line-height:1.5;color:var(--mut)}
#clusterApp .cl-card:nth-child(1){--accent:var(--g800);--tint:#E3F4EA;background:linear-gradient(160deg,#FFFDF5,#fff 45%)}
#clusterApp .cl-card:nth-child(1) strong{color:var(--g900)}
#clusterApp .cl-card:nth-child(2){--accent:var(--teal);--tint:#E1F4F2}
#clusterApp .cl-card:nth-child(3){--accent:var(--info);--tint:var(--infobg)}
#clusterApp .cl-card:nth-child(4){--accent:var(--bad);--tint:var(--badbg)}
#clusterApp .cl-card:nth-child(5){--accent:var(--special);--tint:var(--specialbg)}
#clusterApp .cl-card:nth-child(6){--accent:var(--g700);--tint:var(--mint)}
#clusterApp .cl-card:nth-child(6) p{white-space:pre-line;font-size:12px;line-height:1.7;color:var(--ink2)}
#clusterApp .cl-walk-line{display:flex;justify-content:space-between;gap:10px;font-size:13px;margin:4px 0 0;color:var(--ink2)}
#clusterApp .cl-walk-line b{color:var(--special);font-weight:800}

/* ---------- 7. Panels / sections ---------- */
#clusterApp .cl-panel,#clusterApp #bcc-race{position:relative;margin:0 0 16px!important;border:1px solid var(--line)!important;border-radius:var(--r-lg);
  background:var(--card)!important;box-shadow:var(--sh1);overflow:hidden;scroll-margin-top:calc(var(--clx-sticky-h) + 12px)}
#clusterApp #cl-overview{scroll-margin-top:calc(var(--clx-sticky-h) + 12px)}
#clusterApp .cl-panel-title,#clusterApp .bcc-panel-head{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;
  padding:12px 16px!important;border-bottom:1px solid var(--line)!important;
  background:linear-gradient(100deg,#E6F4EC 0%,#F4FAF6 55%,#fff 100%)!important;position:relative}
#clusterApp .cl-panel-title::before,#clusterApp .bcc-panel-head::before{content:"";position:absolute;left:0;top:0;bottom:0;width:4px;background:linear-gradient(180deg,var(--g700),var(--teal))}
#clusterApp .cl-panel-title h2,#clusterApp .bcc-panel-head h2{margin:0 0 2px;font-size:18px;font-weight:750;color:var(--g900)}
#clusterApp .cl-panel-title p,#clusterApp .bcc-panel-head p{margin:0;font-size:12.5px;color:var(--mut)}
#clusterApp .cl-panel-title h2,#clusterApp .bcc-panel-head h2{cursor:pointer}
#clusterApp .cl-panel-title>a{display:inline-flex;align-items:center;gap:4px;padding:7px 12px;border:1px solid var(--g700);border-radius:var(--r-sm);
  font-size:13px;text-decoration:none;color:var(--g800);background:#fff}
#clusterApp .cl-panel-title>a:hover{background:var(--g800);color:#fff}
#clusterApp .bcc-panel-body{padding:12px}
#clusterApp .bcc-race-actions{display:flex;align-items:center;gap:10px;flex-wrap:wrap;justify-content:flex-end}
#clusterApp .cl-section-tools{display:flex;gap:4px;flex-shrink:0;margin-left:auto}
#clusterApp .cl-section-tools button{font-size:12px;padding:5px 9px;color:var(--mut);background:#fff}
#clusterApp .cl-section-tools button.clx-col{min-width:32px;font-size:13px;color:var(--g800);font-weight:800}
#clusterApp .clx-collapsed>:not(.cl-panel-title):not(.bcc-panel-head){display:none!important}
#clusterApp .clx-collapsed>.cl-panel-title,#clusterApp .clx-collapsed>.bcc-panel-head{border-bottom:0!important}
#clusterApp .clx-collapsed>.cl-panel-title p::after,#clusterApp .clx-collapsed>.bcc-panel-head p::after{content:" · collapsed — click title to open";color:var(--gold);font-weight:600}

/* compare controls */
#clusterApp .cl-compare-controls{display:flex;gap:6px;align-items:center;flex-wrap:wrap}
#clusterApp .cl-compare-controls select,#clusterApp .cl-compare-controls input{min-height:32px;padding:5px 8px;font-size:13px}
#clusterApp #cl-compare-apply{background:var(--g800);color:#fff;border-color:var(--g800)}
#clusterApp #cl-compare-apply:hover:not(:disabled){background:var(--g900)}

/* filters */
#clusterApp .cl-filters{display:flex;flex-wrap:wrap;align-items:center;gap:8px;padding:10px 16px;border-bottom:1px solid var(--line2);background:var(--mint3)}
#clusterApp .cl-filters label{display:flex;align-items:center;gap:6px;margin:0;font-size:12.5px;font-weight:600;color:var(--ink2)}
#clusterApp .cl-filters span{font-size:12px;color:var(--mut)}
#clusterApp .cl-filters button{border-radius:20px;padding:6px 14px}
#clusterApp .cl-filters button.on,#clusterApp #cl-dues-tabs button.on{background:var(--g800);color:#fff;border-color:var(--g800)}
#clusterApp .cl-ap-toolbar{flex-wrap:nowrap}
#clusterApp .cl-ap-toolbar input{flex:1.4;min-width:180px}
#clusterApp .cl-ap-toolbar select{flex:1;min-width:140px;max-width:280px}
#clusterApp .cl-ex-toolbar{flex-wrap:wrap}
#clusterApp .cl-ex-toolbar select{max-width:240px}
#clusterApp #cl-ex-periods{margin-left:auto;font-size:12px!important;color:var(--mut)}
#clusterApp #cl-dues-tabs{flex-wrap:wrap}
#clusterApp .cl-due-range{display:flex;align-items:center;gap:8px;margin-left:auto;flex-wrap:wrap}
#clusterApp .cl-due-range input{width:150px}
#clusterApp .cl-due-range input:disabled{opacity:.5;background:#F1F4F2}

/* summary strip */
#clusterApp .cl-summary{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:10px;padding:12px 16px;background:var(--mint3);border-bottom:1px solid var(--line2)}
#clusterApp .cl-summary>div{background:#fff;border:1px solid var(--line);border-radius:var(--r-md);padding:10px 12px;min-width:0}
#clusterApp .cl-summary small{display:block;font-size:11.5px;font-weight:700;letter-spacing:.3px;text-transform:uppercase;color:var(--mut)}
#clusterApp .cl-summary strong{display:block;font-size:22px;font-weight:800;color:var(--g900);margin-top:2px}
#clusterApp #cl-recovery .cl-summary>div:nth-child(1) strong{color:var(--bad)}
#clusterApp #cl-recovery .cl-summary>div:nth-child(2) strong{color:var(--ok)}
#clusterApp #cl-recovery .cl-summary>div:nth-child(3) strong{color:var(--warn)}
#clusterApp #cl-recovery .cl-summary>div:nth-child(4) strong{color:var(--mut)}

/* conversions */
#clusterApp .cl-conversions{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;padding:14px 16px}
#clusterApp .cl-convert{position:relative;background:#fff;border:1px solid var(--line);border-top:3px solid var(--accent);border-radius:var(--r-md);
  padding:12px 14px;box-shadow:var(--sh1);cursor:pointer;transition:transform .15s,box-shadow .15s}
#clusterApp .cl-convert:hover{transform:translateY(-2px);box-shadow:var(--sh2)}
#clusterApp .cl-convert>b{display:inline-block;color:#fff;background:var(--accent);font-size:13px;font-weight:800;border-radius:6px;padding:3px 8px}
#clusterApp .cl-convert>strong{float:right;font-size:24px;font-weight:800;line-height:1;color:var(--accent)}
#clusterApp .cl-convert>strong small{font-size:12px;font-weight:600;color:var(--mut)}
#clusterApp .cl-convert p{clear:both;margin:10px 0 6px;font-size:12.5px;color:var(--ink2)}
#clusterApp .cl-convert p b{color:var(--ink)}
#clusterApp .cl-convert progress{width:100%;height:6px;accent-color:var(--accent);border-radius:4px}
#clusterApp .cl-convert-employees{max-height:132px;overflow:auto;margin-top:8px;border-top:1px dashed var(--line);padding-top:4px;scrollbar-width:thin}
#clusterApp .cl-convert-employees>div{display:flex;justify-content:space-between;gap:8px;padding:4px 6px;font-size:12.5px;color:var(--ink2);border-radius:5px}
#clusterApp .cl-convert-employees>div:first-child{background:var(--goldbg)}
#clusterApp .cl-convert-employees b{font-size:12.5px}

/* ---------- 8. Tables ---------- */
#clusterApp .cl-table-wrap{max-height:460px;overflow:auto;scrollbar-width:thin}
#clusterApp table{width:100%;border-collapse:separate;border-spacing:0;white-space:nowrap;font-size:13px}
#clusterApp th{position:sticky;top:0;z-index:2;background:#EEF5F1;color:var(--ink2);font-size:12px;font-weight:700;letter-spacing:.2px;
  text-align:right;padding:10px 12px;border-bottom:1px solid var(--line);white-space:nowrap}
#clusterApp th:first-child,#clusterApp td:first-child{text-align:left}
#clusterApp td{padding:9px 12px;text-align:right;border-top:0;border-bottom:1px solid var(--line2);color:var(--ink);font-size:13px}
#clusterApp tbody tr:nth-child(even) td{background:#FAFCFB}
#clusterApp tbody tr:hover td{background:#EEF8F2}
#clusterApp td small{display:block;font-size:11.5px;color:var(--mut);margin-top:1px}
#clusterApp td b,#clusterApp td strong{color:var(--g900)}
#clusterApp .cl-code{display:inline-grid;place-items:center;min-width:36px;height:28px;padding:0 6px;border-radius:7px;background:var(--mint);color:var(--g800);font-size:12px;font-weight:800}
#clusterApp .cl-total td,#clusterApp tr.cl-total td{background:#E3F1E8!important;color:var(--g950)!important;font-weight:800;border-top:2px solid #9CC9AF!important;border-bottom:0}
#clusterApp .cl-progress{display:block;width:90px;height:5px;background:#E4EEE8;border-radius:4px;overflow:hidden;margin:5px 0 0 auto}
#clusterApp .cl-progress i{display:block;height:100%;background:linear-gradient(90deg,var(--g600),var(--g800))}
#clusterApp .cl-more{display:block;margin:10px auto;padding:8px 18px;border-radius:20px;background:var(--g800);color:#fff;border-color:var(--g800);font-size:12.5px}
#clusterApp .cl-more:hover:not(:disabled){background:var(--g900)!important;color:#fff}
#clusterApp .cl-more:disabled{background:var(--mint);color:var(--g800);border-color:var(--line)}

/* drill-down affordance on branch cells (click → branch menu) */
#clusterApp #cl-branches tr:not(.cl-total) td:first-child,
#clusterApp #cl-billing-dues tbody tr:not(.cl-total) td:first-child,
#clusterApp #cl-recovery>.cl-table-wrap tbody tr:not(.cl-total) td:first-child,
#clusterApp #cl-absence tbody td:first-child,
#clusterApp #cl-approvals tbody tr:not(.cl-total) td:first-child,
#clusterApp #cl-execution>.cl-table-wrap:first-of-type tbody tr:not(.cl-total) td:first-child{cursor:pointer}
#clusterApp #cl-branches tr:not(.cl-total) td:first-child b,
#clusterApp #cl-billing-dues tbody tr:not(.cl-total) td:first-child,
#clusterApp #cl-approvals tbody tr:not(.cl-total) td:first-child,
#clusterApp #cl-absence tbody td:first-child b,
#clusterApp #cl-recovery>.cl-table-wrap tbody tr:not(.cl-total) td:first-child,
#clusterApp #cl-execution>.cl-table-wrap:first-of-type tbody tr:not(.cl-total) td:first-child{color:var(--g700);font-weight:800;text-decoration:underline dotted 1px;text-underline-offset:3px}
#clusterApp tr.clx-flash td{animation:clxFlash 2.4s ease-out}
@keyframes clxFlash{0%,35%{background:#FFF1C2}100%{background:inherit}}

/* semantic column colours */
#clusterApp #cl-branches td:nth-child(5),#clusterApp #cl-billing-dues td:nth-child(4),#clusterApp #cl-billing-dues td:last-child,
#clusterApp #cl-recovery td:nth-child(3),#clusterApp #cl-recovery td:last-child{color:var(--bad)!important;font-weight:650}
#clusterApp #cl-billing-dues td:nth-child(5),#clusterApp #cl-recovery td:nth-child(5){color:var(--warn)!important;font-weight:650}
#clusterApp #cl-branches td:nth-child(9){color:var(--g900)!important}
#clusterApp #cl-branches td:nth-child(10){color:var(--info)!important}
#clusterApp #cl-billing-dues td small{color:var(--warn);font-weight:600}

/* comparison table density */
#clusterApp #cl-comparison th,#clusterApp #cl-comparison td{padding:10px 10px}

/* absence */
#clusterApp #cl-absence table{table-layout:fixed;width:100%;min-width:0}
#clusterApp #cl-absence th:first-child,#clusterApp #cl-absence td:first-child{width:72px}
#clusterApp #cl-absence th:nth-child(2),#clusterApp #cl-absence td:nth-child(2){white-space:normal!important;text-align:left!important}
#clusterApp #cl-absence th:last-child,#clusterApp #cl-absence td:last-child{width:76px;text-align:center!important;font-weight:800}
#clusterApp .cl-absence{display:inline-flex;align-items:center;gap:8px;margin:3px 6px 3px 0;padding:5px 9px;border-radius:7px;white-space:nowrap;font-size:12.5px;
  border:1px solid var(--branch-color,#9DB8A9);background:#fff;color:var(--branch-color,var(--g800))}
@supports (background:color-mix(in srgb,red 10%,white)){#clusterApp .cl-absence{background:color-mix(in srgb,var(--branch-color) 7%,white)}}
#clusterApp .cl-absence b{color:var(--ink)}
#clusterApp .cl-absence small{display:inline!important;margin:0!important;color:var(--mut)!important;font-size:12px}
#clusterApp .cl-p,#clusterApp .cl-a{display:inline-block!important;font-style:normal;font-weight:800;border-radius:5px;padding:2px 6px;font-size:11.5px}
#clusterApp .cl-p{background:var(--okbg);color:var(--ok)!important}
#clusterApp .cl-a{background:var(--warnbg);color:var(--warn)!important}
#clusterApp .cl-worst{background:var(--badbg)!important;border-color:var(--bad)!important}
#clusterApp .cl-worst .cl-a{background:var(--bad);color:#fff!important}
#clusterApp .cl-worst>b{color:var(--bad)!important}

/* appointments */
#clusterApp #cl-ap-content .cl-table-wrap{max-height:540px;overflow:auto}
#clusterApp #cl-ap-content table{table-layout:fixed;width:100%;min-width:0;font-size:13px}
#clusterApp #cl-ap-content th,#clusterApp #cl-ap-content td{white-space:normal;overflow-wrap:anywhere;text-align:left!important;vertical-align:middle;padding:9px 10px}
#clusterApp #cl-ap-content th:first-child{width:7%}#clusterApp #cl-ap-content th:nth-child(2){width:19%}
#clusterApp #cl-ap-content th:nth-child(3){width:12%}#clusterApp #cl-ap-content th:nth-child(4){width:13%}
#clusterApp #cl-ap-content th:nth-child(5){width:18%}#clusterApp #cl-ap-content th:nth-child(6){width:13%}
#clusterApp #cl-ap-content details{margin:0;border:0}
#clusterApp #cl-ap-content summary{background:transparent;padding:2px 0;font-size:12.5px;color:var(--g700)}
#clusterApp .cl-section-note{margin:0;padding:10px 16px 6px;font-size:12.5px;color:var(--mut)}

/* executions / misc */
#clusterApp #cl-execution th,#clusterApp #cl-execution td{text-align:left!important}
#clusterApp .cl-mini-title{margin:0;padding:14px 16px 8px;font-size:15px;font-weight:750;color:var(--g900);border-top:1px solid var(--line2)}
#clusterApp details{margin:12px 16px;border:1px solid var(--line);border-radius:var(--r-md);background:#fff;overflow:hidden}
#clusterApp details>summary{padding:10px 14px;background:var(--mint3);font-size:13.5px;font-weight:700;color:var(--g800);cursor:pointer;list-style:none}
#clusterApp details>summary::-webkit-details-marker{display:none}
#clusterApp details>summary::before{content:"▸";display:inline-block;margin-right:8px;transition:transform .15s;color:var(--g700)}
#clusterApp details[open]>summary::before{transform:rotate(90deg)}
#clusterApp details>summary:hover{background:var(--mint)}
#clusterApp .cl-empty{margin:0;padding:22px 16px;color:var(--mut);font-size:13px;text-align:center}
#clusterApp .cl-footnote{margin:0;padding:10px 16px 12px;max-width:none;font-size:12px;line-height:1.6;color:var(--mut2);border-top:1px solid var(--line2)}
#clusterApp main>section>.cl-footnote,#clusterApp #cl-overview>.cl-footnote{border:1px dashed var(--line);border-radius:var(--r-md);background:#fff;margin-top:6px}

/* ---------- 9. Sales Race board (inline #lsrb) ---------- */
#clusterApp #lsrb{--rh:38px;padding-top:0;font-family:inherit}
#clusterApp #lsrb .lsrb-body{gap:12px;padding:4px 0;align-items:stretch}
#clusterApp #lsrb .lsrb-card{border-color:var(--line);border-radius:var(--r-md);box-shadow:var(--sh1)}
#clusterApp #lsrb .lsrb-card-h{padding:9px 12px;font-size:14.5px}
#clusterApp #lsrb .lsrb-card-h span{font-size:12px}
#clusterApp #lsrb .lanes{padding:8px;gap:8px}
#clusterApp #lsrb .race-card .lanes{flex:1;display:grid;grid-template-rows:repeat(4,minmax(70px,1fr))}
#clusterApp #lsrb .lane{gap:8px;min-height:0}
#clusterApp #lsrb .lane-info{gap:2px;padding:5px 9px;justify-content:center}
#clusterApp #lsrb .li-cl{font-size:10px;text-align:right;padding-right:4px;line-height:12px}
#clusterApp #lsrb .li-head{font-size:14px;font-weight:600}
#clusterApp #lsrb .li-br{font-size:11px}
#clusterApp #lsrb .li-stats small{font-size:10px}
#clusterApp #lsrb .li-who .av{--s:28px!important}
#clusterApp #lsrb .lane-track{min-height:70px}
#clusterApp #lsrb .lane-pct{font-size:11px;letter-spacing:0;color:#FFF0C2;font-weight:700}
#clusterApp #lsrb .champs{margin-top:0;padding:2px 8px 8px}
#clusterApp #lsrb .ch-h{margin:2px 2px 8px;font-size:11px}
#clusterApp #lsrb .champ{gap:10px;padding:16px 12px 10px;border-width:1px!important;box-shadow:none!important}
#clusterApp #lsrb .champ::before{border-width:0!important}
#clusterApp #lsrb .champ .av{--s:48px!important}
#clusterApp #lsrb .ch-tx small{font-size:10px;letter-spacing:1.2px}
#clusterApp #lsrb .ch-tx b{font-size:18px}
#clusterApp #lsrb .ch-tx span{font-size:12px}
#clusterApp #lsrb .ch-pills em{font-size:10.5px;padding:2px 7px}
#clusterApp #lsrb .board-hd{font-size:11px;padding:7px 10px;color:var(--mut)}
#clusterApp #lsrb .board-hd,#clusterApp #lsrb .row{grid-template-columns:32px 42px minmax(0,1fr) 112px 40px 40px 40px 30px}
#clusterApp #lsrb .board{margin:6px 6px 6px;min-height:calc(var(--rh) * 11 + 4px)}
#clusterApp #lsrb .row{margin:0;cursor:pointer}
#clusterApp #lsrb .row:hover{box-shadow:inset 0 0 0 1px #A9D9BF;background:#F2FAF5}
#clusterApp #lsrb .nm-l{flex-wrap:nowrap}
#clusterApp #lsrb .nm-l b{font-size:13px}
#clusterApp #lsrb .nm .te{font-size:11.5px;white-space:nowrap}
#clusterApp #lsrb .num{font-size:13px}
#clusterApp #lsrb .collected{color:var(--g800);font-weight:800;font-size:12.5px}
#clusterApp #lsrb .r1 .collected{color:#8A5A06}
#clusterApp #lsrb .mv.chase{color:var(--g600);animation:raceChase 1.4s ease-in-out infinite}
@keyframes raceChase{50%{transform:translateY(-3px)}}
#clusterApp #lsrb .lsrb-status{font-size:12px}
#clusterApp #lsrb button{padding:4px 9px}
#clusterApp #lsrbHigh{border-top:1px solid var(--line);padding:10px 12px}
#clusterApp #lsrbHigh h3{display:flex;align-items:baseline;flex-wrap:wrap;gap:8px;margin:0 0 8px;font-size:15.5px;color:var(--g900)}
#clusterApp #lsrbHigh h3 small{display:inline;font-size:12px;font-weight:500;color:var(--mut)}
#clusterApp #lsrbHigh .hi-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px}
#clusterApp #lsrbHigh .hi-card{display:flex;align-items:center;gap:8px;min-height:52px;padding:7px 9px;border:1px solid #E4CE92;border-radius:var(--r-md);
  background:linear-gradient(115deg,#FFFDF5,#F3F9F5);min-width:0}
#clusterApp #lsrbHigh .hi-card strong{color:#8A5A06;font-size:13px}
#clusterApp #lsrbHigh .hi-card .av{--s:30px!important;flex-shrink:0}
#clusterApp #lsrbHigh .hi-card b{font-size:12.5px;overflow-wrap:normal}
#clusterApp #lsrbHigh .hi-card small{display:block;font-size:11px;color:var(--mut)}
#clusterApp #lsrb::after{content:'';position:absolute;left:0;bottom:0;height:2px;width:100%;pointer-events:none;opacity:0;z-index:3;
  background:linear-gradient(90deg,transparent 0%,transparent 25%,#df8b12 42%,#ffd15b 49%,#fff4bf 52%,transparent 68%);background-size:200% 100%}
#clusterApp #lsrb.race-refreshing::after{opacity:1;animation:raceRefreshTail .65s linear infinite!important}
@keyframes raceRefreshTail{from{background-position:200% 0}to{background-position:-200% 0}}

/* ---------- 10. Drill menu / toast / back-to-top (added by script) ---------- */
.clx-menu{position:fixed;z-index:9999;min-width:240px;max-width:300px;background:#fff;border:1px solid #CFE2D7;border-radius:12px;
  box-shadow:0 14px 40px rgba(4,40,26,.22);padding:6px;font:13px/1.4 Inter,"Segoe UI",system-ui,sans-serif;color:#1B2A24;animation:clxIn .14s ease-out}
@keyframes clxIn{from{opacity:0;transform:translateY(-4px)}}
.clx-menu header{display:flex;align-items:center;gap:8px;padding:8px 10px 9px;border-bottom:1px solid #E8F0EB;margin-bottom:4px}
.clx-menu header b{display:inline-grid;place-items:center;min-width:34px;height:26px;padding:0 6px;border-radius:6px;background:#0A5636;color:#fff;font-size:12px}
.clx-menu header span{font-weight:700;color:#063D27;font-size:14px}
.clx-menu button{display:flex;align-items:center;gap:10px;width:100%;text-align:left;border:0;background:transparent;border-radius:8px;
  padding:8px 10px;font:inherit;font-size:13px;color:#1B2A24;cursor:pointer}
.clx-menu button:hover,.clx-menu button:focus-visible{background:#ECF8F1;color:#063D27;outline:0}
.clx-menu button i{font-style:normal;width:20px;text-align:center}
.clx-menu button small{margin-left:auto;color:#7D8E86;font-size:11px}
.clx-menu p{margin:4px 10px 8px;font-size:12px;color:#7D8E86}
.clx-toast{position:fixed;left:50%;bottom:24px;z-index:9999;transform:translate(-50%,20px);opacity:0;pointer-events:none;
  background:#063D27;color:#fff;font:600 13px Inter,system-ui,sans-serif;padding:10px 18px;border-radius:24px;box-shadow:0 8px 24px rgba(0,0,0,.25);transition:.25s}
.clx-toast.on{opacity:1;transform:translate(-50%,0)}
.clx-top{position:fixed;right:22px;bottom:22px;z-index:9998;width:44px;height:44px;border-radius:50%;border:0;cursor:pointer;
  background:linear-gradient(135deg,#0A5636,#0F766E);color:#fff;font-size:18px;box-shadow:0 6px 18px rgba(4,40,26,.3);
  opacity:0;transform:translateY(12px);pointer-events:none;transition:.2s}
.clx-top.on{opacity:1;transform:none;pointer-events:auto}
.clx-top:hover{filter:brightness(1.12)}

/* ---------- 11. Responsive ---------- */
@media(max-width:1400px){#clusterApp .cl-cards{grid-template-columns:repeat(3,minmax(0,1fr))}}
@media(max-width:1100px){
  #clusterApp #lsrb{--rh:40px}
  #clusterApp #lsrb .nm-l{flex-wrap:wrap}#clusterApp #lsrb .nm .te{font-size:10.5px}
  #clusterApp .cl-conversions{grid-template-columns:repeat(2,minmax(0,1fr))}
  #clusterApp #lsrbHigh .hi-grid{grid-template-columns:repeat(2,minmax(0,1fr))}
}
@media(max-width:900px){
  #clusterApp #lsrb .race-card .lanes{flex:initial;grid-template-rows:repeat(4,minmax(76px,auto))}
  #clusterApp .cl-score .cl-score-ticker{display:none}
  #clusterApp .cl-ap-toolbar{flex-wrap:wrap}
  #clusterApp .cl-due-range{margin-left:0}
}
@media(max-width:700px){
  #clusterApp{padding:0 12px 28px}
  #clusterApp .cl-header,#clusterApp .clx-sticky{margin:0 -12px;padding-left:12px;padding-right:12px}
  #clusterApp .cl-header{align-items:flex-start;flex-direction:column;gap:12px}
  #clusterApp .cl-brand h1{font-size:21px}
  #clusterApp .cl-controls{width:100%}
  #clusterApp .cl-controls label{flex:1}#clusterApp .cl-controls select{min-width:0;flex:1}
  #clusterApp .cl-score{display:grid;grid-template-columns:1fr 1fr;font-size:12px}
  #clusterApp .cl-score>div{padding:7px 10px;border-bottom:1px solid rgba(255,255,255,.1)}
  #clusterApp .cl-cards{grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}
  #clusterApp .cl-card{min-height:116px;padding:12px 12px 28px}
  #clusterApp .cl-card strong{font-size:21px}
  #clusterApp .cl-conversions{grid-template-columns:minmax(0,1fr)}
  #clusterApp #lsrb{--rh:50px}
  #clusterApp #lsrb .board-hd,#clusterApp #lsrb .row{grid-template-columns:28px 38px minmax(0,1fr) 84px 30px 30px 30px 22px}
  #clusterApp #lsrb .nm .te{display:block;white-space:normal}
  #clusterApp #lsrbHigh .hi-grid{grid-template-columns:minmax(0,1fr)}
  #clusterApp #cl-absence table{min-width:620px}
  #clusterApp #cl-ap-content thead{display:none}
  #clusterApp #cl-ap-content table,#clusterApp #cl-ap-content tbody{display:block}
  #clusterApp #cl-ap-content tbody tr{display:grid;grid-template-columns:1fr 1fr;height:auto;padding:8px;border-bottom:1px solid var(--line)}
  #clusterApp #cl-ap-content tbody td{display:block!important;width:auto!important;min-width:0!important;padding:5px 8px;border:0;font-size:12.5px}
  #clusterApp #cl-ap-content td::before{content:attr(data-label);display:block;font-size:10.5px;font-weight:700;text-transform:uppercase;color:var(--mut2);margin-bottom:2px}
  #clusterApp #cl-ap-content td:first-child{grid-column:1/-1;font-weight:700}
  #clusterApp #cl-ap-content td:first-child::before{display:inline;margin-right:7px}
  #clusterApp #cl-ap-content td:last-child{grid-column:1/-1}
  #clusterApp .cl-section-tools button:not(.clx-col){display:none}
  .clx-top{right:14px;bottom:14px}
  #clusterApp .clx-focus small{display:none}
  #clusterApp .clx-focus span{white-space:nowrap;font-size:12.5px}
}
@media(prefers-reduced-motion:reduce){
  html{scroll-behavior:auto}
  #clusterApp *,#clusterApp *::before,#clusterApp *::after{animation:none!important;transition:none!important}
}

/* ---------- 12. Print (single section) ---------- */
@media print{
  body.cl-printing *{visibility:hidden}
  body.cl-printing .cl-print-target,body.cl-printing .cl-print-target *{visibility:visible}
  body.cl-printing #cl-overview>:not(.cl-print-target),body.cl-printing .cl-header,body.cl-printing .clx-sticky,
  body.cl-printing .cl-tabs,body.cl-printing .cl-score,body.cl-printing .clx-top,body.cl-printing .clx-toast{display:none!important}
  body.cl-printing .cl-print-target{position:static!important;width:100%;margin:0!important;box-shadow:none!important}
  body.cl-printing .cl-print-target>*{display:revert!important}
  body.cl-printing .cl-print-target .cl-table-wrap{max-height:none;overflow:visible}
  body.cl-printing .cl-print-target tr[hidden]{display:table-row!important}
  body.cl-printing .cl-section-tools,body.cl-printing .cl-more{display:none!important}
  body.cl-printing .cl-print-target details>*{display:block!important}
  body.cl-printing #cl-overview,body.cl-printing main,body.cl-printing #clusterApp{margin:0!important;padding:0!important;max-width:none!important;width:100%!important}
  body.cl-printing th{position:static}
}
/* Fine gold / pearl / forest design system */
body{background:#f3f5f2!important}
#clusterApp{--forest:#103d30;--green:#186147;--gold:#b69a57;--line:#e4e8df;--muted:#69776f;background:transparent!important;color:#233b31;font-family:Inter,-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;padding:12px 22px 28px;max-width:1800px}
#clusterApp .cl-header{position:relative;padding:17px 22px;border:1px solid #c4aa68;border-radius:14px;background:linear-gradient(115deg,#092f25,#164b39 70%,#205740);box-shadow:inset 0 1px 0 #f8e8b54d,0 8px 24px #163e2910}
#clusterApp .cl-header:after{content:'';position:absolute;bottom:0;left:24px;right:24px;height:1px;background:linear-gradient(90deg,transparent,#f4df9f,transparent);pointer-events:none}
#clusterApp .cl-brand h1{font-size:24px;letter-spacing:-.6px;font-weight:650;line-height:1.2}
#clusterApp .cl-brand small{color:#dcc88e;letter-spacing:2px;font-size:9px}
#clusterApp .cl-brand p{color:#e4d8ad;font-size:11px;margin-top:4px}
#clusterApp .cl-tabs{gap:5px;padding:12px 0 10px;align-items:center;flex-wrap:wrap}
#clusterApp .cl-tabs button{padding:7px 11px!important;font-size:11px!important;border:1px solid #d7c797!important;background:linear-gradient(#fffef9,#f5f6ee)!important;color:#315647!important;box-shadow:inset 0 1px 0 #fff;border-radius:8px}
#clusterApp .cl-tabs button:hover,#clusterApp .cl-tabs button.active{background:linear-gradient(120deg,#184d39,#24664a)!important;color:#fff4d4!important;border-color:#c3a45e!important}
#clusterApp button,#clusterApp select,#clusterApp input{border:1px solid #d7ccab;border-radius:7px;min-height:30px;line-height:1.25;transition:background .15s,border-color .15s,box-shadow .15s}
#clusterApp button:hover{box-shadow:0 2px 8px #163e2910;border-color:#b18d3b}
#clusterApp button:disabled{cursor:default;opacity:.55;box-shadow:none}
#clusterApp select,#clusterApp input{background:#fffefa;color:#254b38;padding:6px 9px}
#clusterApp .cl-score{min-height:34px;margin-bottom:12px;border:1px solid #bda263;border-radius:9px;background:linear-gradient(110deg,#123c2e,#21543f);box-shadow:inset 0 1px 0 #f9e9b433,0 3px 10px #173e2c0c;font-size:11px}
#clusterApp .cl-score>div{padding:0 12px;border-right-color:#d6bf7440}
#clusterApp .cl-cards{gap:10px;margin:0 0 12px;align-items:stretch}
#clusterApp .cl-card{border:1px solid #d3c18c!important;border-left:2px solid var(--card-color,#b89a53)!important;border-radius:11px!important;padding:14px 14px 12px 17px!important;background:linear-gradient(125deg,#fffefb,#f5f8f1)!important;box-shadow:inset 0 1px 0 #fff,0 4px 13px #153d2508!important;text-align:left}
#clusterApp .cl-card small{font-size:11px;color:#69766d;font-weight:550;letter-spacing:.1px}
#clusterApp .cl-card strong{font-size:clamp(21px,1.8vw,29px);font-weight:750;letter-spacing:-.7px;line-height:1.2;margin:7px 0;color:#15593e}
#clusterApp .cl-card p{font-size:10px;line-height:1.6;color:#58695c}
#clusterApp .cl-panel,#clusterApp #bcc-race{position:relative;border:1px solid #cbb679!important;border-radius:12px!important;background:#fffefb!important;margin-bottom:12px;box-shadow:inset 0 1px 0 #fff,0 4px 16px #143c2907!important;overflow:hidden}
#clusterApp .cl-panel-title,#clusterApp .bcc-panel-head{position:relative;padding:11px 16px!important;min-height:54px;border-bottom:1px solid #dfd3ac!important;background:linear-gradient(105deg,#eef4e7 0%,#fafbf5 55%,#fff9eb 100%)!important;gap:10px;align-items:center}
#clusterApp .cl-panel-title:before,#clusterApp .bcc-panel-head:before{content:'';position:absolute;top:0;left:14px;right:14px;height:1px;background:linear-gradient(90deg,transparent,#ead698,#fff5d6,#d5bd76,transparent);pointer-events:none}
#clusterApp .cl-panel-title h2,#clusterApp .bcc-panel-head h2{font-size:16px!important;line-height:1.25;font-weight:700;letter-spacing:-.15px;margin:0 0 3px;color:#174a35!important}
#clusterApp .cl-panel-title p,#clusterApp .bcc-panel-head p{font-size:10px!important;line-height:1.4;color:#708073!important;margin:0}
#clusterApp .cl-section-tools{display:flex;align-items:center;gap:5px;flex-shrink:0}
#clusterApp .cl-section-tools button{min-height:27px;padding:4px 8px;font-size:10px;background:#fffdf6;border-color:#d8cca6;color:#44604c;box-shadow:inset 0 1px 0 white}
#clusterApp .cl-conversions{padding:12px;gap:10px}
#clusterApp .cl-convert{border:1px solid #d7cba5!important;border-radius:10px;padding:13px;background:linear-gradient(135deg,#fff,#f6f9f2)!important;box-shadow:none!important}
#clusterApp .cl-convert-employees{margin-top:9px;padding-top:6px;border-top:1px solid #e7e5d5}
#clusterApp .cl-convert-employees>div{font-size:11px;padding:4px 5px}
#clusterApp .cl-convert-employees>div:first-child{background:#f6f0dd;border-radius:5px}
#clusterApp .cl-table-wrap{scrollbar-width:thin;scrollbar-color:#c2b488 #f0f3ed}
#clusterApp th{padding:10px 12px!important;font-size:10px!important;letter-spacing:.15px;color:#526858!important;background:#f0f4ea!important;border-bottom:1px solid #dce4d5!important;vertical-align:middle}
#clusterApp td{padding:11px 12px!important;font-size:12px;border-top:0;border-bottom:1px solid #e8ece4!important;vertical-align:middle}
