  html:not(.life-race-amounts-allowed) #lsrb .board-hd>span:nth-child(4){display:none!important}
  html:not(.life-race-amounts-allowed) #lsrb .board-hd,
  html:not(.life-race-amounts-allowed) #lsrb .row{grid-template-columns:26px 34px minmax(100px,1fr) 34px 34px 34px 27px!important}
  html:not(.life-race-amounts-allowed) #lsrb .ch-pills em:has(.life-race-money:only-child){display:none!important}
  `;document.head.append(style);
  function start(){
    const root=document.getElementById('lsrb');if(!root)return;
    function mask(){
      observer.disconnect();
      const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);const nodes=[];let n;
      while(n=walker.nextNode())if(n.textContent.includes('₹')&&!n.parentElement.closest('script,style,.life-race-money'))nodes.push(n);
      nodes.forEach(node=>{
        const text=node.textContent, fragment=document.createDocumentFragment();
        const pattern=/\s*[·/]?\s*₹\s*[\d,]+(?:\.\d+)?(?:\s*(?:net collected|net))?/g;let cursor=0,m;
        while((m=pattern.exec(text))){fragment.append(document.createTextNode(text.slice(cursor,m.index)));const span=document.createElement('span');span.className='life-race-money';span.textContent=m[0];fragment.append(span);cursor=pattern.lastIndex;}
        if(cursor){fragment.append(document.createTextNode(text.slice(cursor)));node.replaceWith(fragment);}
