    }
    const observer=new MutationObserver(mask);mask();
    fetch('/api/method/life_branch_shared_layout',{credentials:'same-origin'}).then(r=>{if(!r.ok)throw Error('Role check unavailable');return r.json();}).then(r=>{
      if(r.message?.can_view_sales_amounts===true)document.documentElement.classList.add('life-race-amounts-allowed');
